def compute(vars):
    total = vars["v1"] + vars["v2"] + vars["v3"]
    count = 3
    average = total / count

    return {
        "value": average,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "v3": vars["v3"],
            "total": total,
            "count": count,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
